{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C44"],
      "claim": "Record C44 reports absolute bioavailability of 77% for a 1500 mg tablet after a meal in healthy volunteers, directly supporting F ≥ 20% under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Record C19 reports mean oral bioavailability of 93% for emtricitabine and states it was unaffected by food, supporting high bioavailability regardless of fed state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Record C14 reports absolute oral bioavailability greater than 90% for prucalopride after a 2 mg oral dose, with absorption not influenced by food intake.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred evidence indicates oral bioavailability well above the 20% threshold, including direct fed-state and food-effect data; therefore predict high.",
  "evidence_gaps": [
    "Molecule 1 includes didanosine records inconsistent with emtricitabine; those inconsistent cards were discounted.",
    "Molecule 2 includes a brigatinib record inconsistent with GSK1322322; that inconsistent card was discounted."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

